    leadAnswerBlock: '**Für US-Käufer ist der klarste Weg zum solaren Heimspeicher im Jahr 2026 eine tragbare Powerstation oder ein erweiterbarer Heimspeicher — kein netzgekoppeltes Balkon-Kit, das mit einem Flickenteppich einzelstaatlicher Regelungen und je nach Versorger unterschiedlichen UL-1741-Anforderungen an die Netzeinbindung konfrontiert ist.** EcoFlows Delta Pro und Delta Pro Ultra führen bei reinen Spezifikationen und Solar-Eingangskapazität; Bluettis AC300+B300-Stack punktet mit LFP-Erweiterbarkeit und modularem Preismodell; Jackery dominiert das Amazon-Verkaufsvolumen mit seiner NMC-Explorer-Reihe; Ankers tragbare SOLIX-Einheiten (die F2000 und F3800) bieten eine starke LFP-Alternative. Alle vier sind in den USA breit über Amazon und die Direktkanäle der Marken verfügbar — die Preise schwanken erheblich durch die Belastung mit Section-301-Zöllen, prüfen Sie daher den aktuellen Preis, statt sich auf eine hier veröffentlichte Zahl zu verlassen.',
