    leadAnswerBlock: '**Pour les acheteurs américains, la voie la plus claire vers le stockage solaire domestique en 2026 est une station électrique portable ou une batterie domestique extensible — et non un kit de balcon raccordé au réseau, confronté à un patchwork juridique d\'un État à l\'autre et à des exigences d\'interconnexion UL 1741 qui varient selon le fournisseur d\'électricité.** Les Delta Pro et Delta Pro Ultra d\'EcoFlow dominent sur les specs brutes et la capacité d\'entrée solaire ; la combinaison AC300+B300 de Bluetti l\'emporte sur l\'extensibilité LFP et la tarification modulaire ; Jackery domine le volume de ventes sur Amazon avec sa gamme Explorer en NMC ; les unités portables Anker SOLIX (les F2000 et F3800) offrent une solide alternative LFP. Les quatre sont largement disponibles sur Amazon et via les canaux directs des marques aux États-Unis — les prix évoluent fortement en raison de l\'exposition aux droits de douane de la Section 301, alors vérifiez le prix actuel plutôt que de vous fier à un chiffre publié ici.',
