          '**賃貸居住者やマンション住まい — 停電時のバックアップ電源（冷蔵庫＋電子機器＋インターネット）。** 2〜3 kWh 帯の中規模 LFP ポータブル電源があれば、冷蔵庫を12〜18時間動かし、スマホ／ノートPC を充電し、一般的な停電を通じてルーターを稼働させるのに十分です。Bluetti AC200MAX や Anker SOLIX F2000 は妥当な出発点です。どちらも LFP、どちらも3 kWh 未満、どちらも Amazon で入手できます。ベランダや屋根にアクセスできるなら、200〜400W のポータブルソーラーパネルと組み合わせて稼働時間を延ばしてください。許認可も系統連系も不要で、パネルを機器のソーラー入力ポートに挿すだけです。',
          '**持ち家所有者、部分的なソーラー＋バックアップ — 本格的な屋根設置なしに夜間消費を相殺したい。** これは EU の Balkonkraftwerk の概念に最も近い用途ですが、系統への送電の側面はありません。EcoFlow Delta Pro（LFP、約3.6 kWh、強力な MPPT 入力。現行スペック要確認）を2〜3枚の400W パネルと組み合わせるのは妥当な構成です。日中はパネルから充電し、夜間に照明や家電のために消費します。負荷要件が増えれば追加バッテリーモジュールで拡張できます。重要な制約は、送電するのではなく自分で貯めたソーラー電力を使う点で、これが連系の問題を丸ごと回避します。',
