          '**スマートホーム／ローカル制御ユーザー — クラウド依存なしで Home Assistant 連携を望む。** これは最も満たしにくい要件で、4ブランドすべてで最も対応が手薄です。EcoFlow は最も活発なコミュニティ連携エコシステムを持ちます（Delta Pro シリーズ向けの HACS ベースの連携が存在します）が、公式サポートではなくコミュニティ保守のため、頼る前に現行状況を確認してください。Bluetti と Anker SOLIX は執筆時点で十分に文書化されたローカル API を欠いています。ローカル制御が好みではなく必須要件なら、ローカル API 対応ハードウェアの現状と、これらの機器が公開以降に変化したかどうかについて [クラウド不要のベランダ発電ガイド](/ja/balcony-solar/home-assistant-balcony-solar-no-cloud) を参照してください。',
