          '**전체 가정 백업 — 장기 정전 중 고부하(HVAC, 전기 스토브, 히트 펌프) 구동을 원하는 경우.** 이는 포터블 파워 스테이션의 범위를 벗어나 전용 홈 배터리 시스템의 영역으로 넘어갑니다. 이 규모에서는 EcoFlow Delta Pro Ultra(약 25+ kWh까지 확장 — 확인)와 (허가와 전기기사 참여가 필요할 수 있는) 전용 홈 배터리 설치가 관련 비교 대상입니다. 이는 위의 포터블 유닛과는 다른 제품 범주이며 별도로 평가해야 합니다.',
